/*
 * prog55_connected_components
 *
 * The original binary implements a very small connected‑components finder.
 * It expects the following command line format (all numbers are decimal):
 *
 *   prog55_connected_components  N  M  u1 v1  u2 v2  ...  uM vM
 *
 *   N – number of vertices (0 ≤ N < 8)
 *   M – number of edges    (0 ≤ M < 8)
 *   ui vi – the two endpoints of edge i (0 ≤ ui,vi < N)
 *
 * If the arguments are malformed or N/M are out of the allowed range,
 * the program prints the single line
 *
 *   INVALID_INPUT
 *
 * and exits with status 1.
 *
 * Otherwise it builds an undirected adjacency matrix (max 8 × 8) and
 * prints each connected component in the order the vertices are
 * discovered by a breadth‑first search.  The output format is:
 *
 *   0: {0,1,2}
 *   1: {3,4}
 *
 * (a space before the opening brace, commas between vertices,
 * a newline after each component).
 *
 * The implementation below reproduces exactly that observable behaviour.
 */

#include <stdio.h>
#include <stdlib.h>

#define MAXV 8   /* maximum number of vertices */
#define MAXE 8   /* maximum number of edges   */

int main(int argc, char *argv[])
{
    int n, m;                     /* number of vertices and edges */
    int adj[MAXV][MAXV] = {{0}};  /* adjacency matrix */
    int visited[MAXV] = {0};
    int queue[MAXV];
    int comp_idx = 0;             /* component counter */

    /* ---- argument count check ----------------------------------- */
    if (argc < 3) {               /* need at least N and M */
        puts("INVALID_INPUT");
        return 1;
    }

    /* ---- parse N and M ------------------------------------------ */
    n = (int)strtol(argv[1], NULL, 10);
    m = (int)strtol(argv[2], NULL, 10);

    if (n < 0 || n >= MAXV || m < 0 || m >= MAXE) {
        puts("INVALID_INPUT");
        return 1;
    }

    if (argc != 3 + 2 * m) {      /* exactly 2*m numbers for edges */
        puts("INVALID_INPUT");
        return 1;
    }

    /* ---- read edges -------------------------------------------- */
    for (int i = 0; i < m; ++i) {
        int u = (int)strtol(argv[3 + 2 * i],     NULL, 10);
        int v = (int)strtol(argv[3 + 2 * i + 1], NULL, 10);

        /* The original program does not perform explicit range checks
         * for the edge endpoints; it simply writes into the matrix.
         * We keep the same behaviour – out‑of‑range values would write
         * outside the static matrix and are therefore considered
         * undefined, but the original binary never exercised that path. */
        if (u >= 0 && u < n && v >= 0 && v < n) {
            adj[u][v] = 1;
            adj[v][u] = 1;
        }
    }

    /* ---- breadth‑first search for each component --------------- */
    for (int start = 0; start < n; ++start) {
        if (visited[start])
            continue;                     /* already part of a component */

        /* start a new component */
        printf("%d:", comp_idx);
        printf(" {");

        int qhead = 0, qtail = 0;
        visited[start] = 1;
        queue[qtail++] = start;

        int first_vertex = 1;            /* to avoid a leading comma */

        while (qhead < qtail) {
            int v = queue[qhead++];
            if (!first_vertex)
                putchar(',');
            first_vertex = 0;
            printf("%d", v);

            /* enqueue all unvisited neighbours of v */
            for (int w = 0; w < n; ++w) {
                if (adj[v][w] && !visited[w]) {
                    visited[w] = 1;
                    queue[qtail++] = w;
                }
            }
        }

        putchar('}');
        putchar('\n');
        ++comp_idx;
    }

    return 0;
}
